package main

import (
	"bytes"
	"crypto/ecdh"
	"crypto/hkdf"
	"crypto/mlkem"
	"crypto/sha256"
	"crypto/sha3"
	"encoding/base64"
	"fmt"
	"os"
	"strings"

	"golang.org/x/crypto/chacha20poly1305"
)

// bech32 decode (no length limit)
const charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

func bech32Decode(s string) (string, []byte, error) {
	s = strings.ToLower(s)
	pos := strings.LastIndex(s, "1")
	hrp := s[:pos]
	data := s[pos+1:]
	var vals []byte
	for _, c := range data {
		i := strings.IndexRune(charset, c)
		if i < 0 {
			return "", nil, fmt.Errorf("bad char %c", c)
		}
		vals = append(vals, byte(i))
	}
	vals = vals[:len(vals)-6]
	// convert 5->8
	var out []byte
	acc := 0
	bits := 0
	for _, v := range vals {
		acc = (acc << 5) | int(v)
		bits += 5
		if bits >= 8 {
			bits -= 8
			out = append(out, byte(acc>>bits))
		}
	}
	return hrp, out, nil
}

func main() {
	_, seed, err := bech32Decode("AGE-SECRET-KEY-PQ-1K30MYPZAHAXHR22YHH27EGDVLU0QNSUH3DSV7J7NR3X6D9LHXNWSDLTV4T")
	if err != nil {
		panic(err)
	}
	fmt.Println("seed len", len(seed))
	// expand
	h := sha3.NewSHAKE256()
	h.Write(seed)
	exp := make([]byte, 96)
	h.Read(exp)
	dk, err := mlkem.NewDecapsulationKey768(exp[:64])
	if err != nil {
		panic(err)
	}
	skX, err := ecdh.X25519().NewPrivateKey(exp[64:96])
	if err != nil {
		panic(err)
	}
	pkX := skX.PublicKey().Bytes()
	pkM := dk.EncapsulationKey().Bytes()
	fmt.Println("pkM", len(pkM), "pkX", len(pkX))

	data, _ := os.ReadFile("/tmp/pq.age")
	idx := bytes.Index(data, []byte("\n--- "))
	hdr := data[:idx+1]
	lines := bytes.Split(hdr, []byte("\n"))
	fields := strings.Fields(string(lines[1]))
	ct, err := base64.RawStdEncoding.DecodeString(fields[2])
	if err != nil {
		panic(err)
	}
	fmt.Println("ct len", len(ct))
	body, err := base64.RawStdEncoding.DecodeString(string(lines[2]))
	if err != nil {
		panic(err)
	}
	ctM := ct[:1088]
	ctX := ct[1088:]
	ssM, err := dk.Decapsulate(ctM)
	if err != nil {
		panic(err)
	}
	ctXpub, err := ecdh.X25519().NewPublicKey(ctX)
	if err != nil {
		panic(err)
	}
	ssX, err := skX.ECDH(ctXpub)
	if err != nil {
		panic(err)
	}
	// X-Wing combiner
	comb := sha3.New256()
	comb.Write(ssM)
	comb.Write(ssX)
	comb.Write(ctX)
	comb.Write(pkX)
	comb.Write([]byte("\\.//^\\"))
	ss := comb.Sum(nil)
	fmt.Printf("xwing ss %x\n", ss)

	try := func(name string, key []byte) bool {
		aead, _ := chacha20poly1305.New(key)
		nonce := make([]byte, 12)
		fk, err := aead.Open(nil, nonce, body, nil)
		if err == nil {
			fmt.Printf("SUCCESS %s: filekey %x\n", name, fk)
			return true
		}
		return false
	}
	try("direct", ss)
	labels := []string{"age-encryption.org/v1/mlkem768x25519", "age-encryption.org/v1/X25519", "age-encryption.org/v1/pq", "mlkem768x25519", "age-encryption.org/v1/xwing"}
	for _, l := range labels {
		for si, salt := range [][]byte{nil, ct, ctX, append(append([]byte{}, ctX...), pkX...), append(append([]byte{}, pkM...), pkX...), append(append([]byte{}, ct...), pkM...), append(append(append([]byte{}, ct...), pkM...), pkX...)} {
			k, _ := hkdf.Key(sha256.New, ss, salt, l, 32)
			try(fmt.Sprintf("hkdf label=%q salt#%d", l, si), k)
		}
	}
	// try alternative combiners
	fmt.Println("done")
}
EOF
