package main

import (
	"bytes"
	"crypto/ecdh"
	"crypto/hkdf"
	"crypto/mlkem"
	"crypto/sha256"
	"crypto/sha3"
	"crypto/sha512"
	"encoding/base64"
	"fmt"
	"hash"
	"os"
	"strings"

	"golang.org/x/crypto/chacha20poly1305"
)

func tryMain() {
	_, seed, _ := bech32Decode("AGE-SECRET-KEY-PQ-1K30MYPZAHAXHR22YHH27EGDVLU0QNSUH3DSV7J7NR3X6D9LHXNWSDLTV4T")
	h := sha3.NewSHAKE256()
	h.Write(seed)
	exp := make([]byte, 96)
	h.Read(exp)
	dk, _ := mlkem.NewDecapsulationKey768(exp[:64])
	skX, _ := ecdh.X25519().NewPrivateKey(exp[64:96])
	pkX := skX.PublicKey().Bytes()
	pkM := dk.EncapsulationKey().Bytes()

	data, _ := os.ReadFile(os.Args[2])
	idx := bytes.Index(data, []byte("\n--- "))
	hdr := data[:idx+1]
	lines := bytes.Split(hdr, []byte("\n"))
	fields := strings.Fields(string(lines[1]))
	ct, _ := base64.RawStdEncoding.DecodeString(fields[2])
	body, _ := base64.RawStdEncoding.DecodeString(string(lines[2]))

	try := func(name string, key []byte) bool {
		aead, _ := chacha20poly1305.New(key)
		nonce := make([]byte, 12)
		fk, err := aead.Open(nil, nonce, body, nil)
		if err == nil {
			fmt.Printf("SUCCESS %s: filekey %x\n", name, fk)
			return true
		}
		return false
	}

	for _, order := range []string{"MX", "XM"} {
		var ctM, ctX []byte
		if order == "MX" {
			ctM, ctX = ct[:1088], ct[1088:]
		} else {
			ctX, ctM = ct[:32], ct[32:]
		}
		ssM, err := dk.Decapsulate(ctM)
		if err != nil {
			fmt.Println(order, "decaps err", err)
			continue
		}
		ctXpub, err := ecdh.X25519().NewPublicKey(ctX)
		if err != nil {
			fmt.Println(order, "x pub err", err)
			continue
		}
		ssX, err := skX.ECDH(ctXpub)
		if err != nil {
			fmt.Println(order, "ecdh err", err)
			continue
		}
		cat := func(parts ...[]byte) []byte {
			var o []byte
			for _, p := range parts {
				o = append(o, p...)
			}
			return o
		}
		label := []byte("\\.//^\\")
		hashes := map[string]func() hash.Hash{"sha3": sha3.New256, "sha256": sha256.New, "sha512": sha512.New}
		inputs := map[string][]byte{
			"xwing":          cat(ssM, ssX, ctX, pkX, label),
			"xwing-nolabel":  cat(ssM, ssX, ctX, pkX),
			"ssM||ssX":       cat(ssM, ssX),
			"ssX||ssM":       cat(ssX, ssM),
			"ssM||ssX||ct||pk": cat(ssM, ssX, ct, pkM, pkX),
			"ssM||ssX||ctX||pkX||ctM||pkM": cat(ssM, ssX, ctX, pkX, ctM, pkM),
			"xwing-age-label":  cat(ssM, ssX, ctX, pkX, []byte("age-encryption.org/v1/mlkem768x25519")),
		}
		for hn, hf := range hashes {
			for in, iv := range inputs {
				hh := hf()
				hh.Write(iv)
				sum := hh.Sum(nil)[:32]
				try(order+" "+hn+" "+in, sum)
				for _, l := range []string{"age-encryption.org/v1/mlkem768x25519", "age-encryption.org/v1/X25519", "mlkem768x25519", "age-encryption.org/v1/pq", "age-encryption.org/v1/mlkem768+x25519"} {
					for si, salt := range [][]byte{nil, ct, ctX, cat(ctX, pkX), cat(pkM, pkX), cat(ct, pkM, pkX)} {
						k, _ := hkdf.Key(sha256.New, sum, salt, l, 32)
						try(fmt.Sprintf("%s %s %s hkdf label=%q salt#%d", order, hn, in, l, si), k)
					}
				}
			}
		}
		// Direct HKDF on ssM||ssX etc
		for in, iv := range inputs {
