		if bytes.Equal(out[:4], tag) {
			fmt.Println("FOUND", name)
			os.Exit(0)
		}
		if len(out) > 4 && bytes.Equal(out[len(out)-4:], tag) {
			fmt.Println("FOUND (suffix)", name)
			os.Exit(0)
		}
	}
	var seqs [][]string
	for n := 1; n <= 3; n++ {
		seqs = append(seqs, perms(names, n)...)
	}
	build := func(s []string) []byte {
		var b []byte
		for _, x := range s {
			b = append(b, comps[x]...)
		}
		return b
	}
	labels := []string{"", "age-encryption.org/v1/p256tag", "age-encryption.org/v1/tag", "tag", "age-encryption.org/v1/p256tag/tag", "age-encryption.org/v1", "p256tag"}
	for _, s := range seqs {
		in := build(s)
		n := strings.Join(s, "|")
		c := crc32.ChecksumIEEE(in)
		check("crc32("+n+")", []byte{byte(c >> 24), byte(c >> 16), byte(c >> 8), byte(c)})
		check("crc32le("+n+")", []byte{byte(c), byte(c >> 8), byte(c >> 16), byte(c >> 24)})
		f := fnv.New32a()
		f.Write(in)
		check("fnv32a("+n+")", f.Sum(nil))
