				check("sha3("+n+" "+lab+")", h3[:])
				h5 := sha512.Sum512(x)
				check("sha512("+n+" "+lab+")", h5[:])
			}
			for _, L := range []int{4, 32, 36} {
				k, _ := hkdf.Key(sha256.New, in, nil, lab, L)
				check(fmt.Sprintf("hkdf(%s,nil,%q,%d)", n, lab, L), k)
			}
		}
	}
	for _, a := range seqs {
		if len(a) > 2 {
			continue
		}
		for _, b := range seqs {
			if len(b) > 2 {
				continue
			}
			ia, ib := build(a), build(b)
			na, nb := strings.Join(a, "|"), strings.Join(b, "|")
			for _, lab := range labels {
				for _, L := range []int{4, 32, 36} {
					k, _ := hkdf.Key(sha256.New, ia, ib, lab, L)
					check(fmt.Sprintf("hkdf(ikm=%s,salt=%s,%q,%d)", na, nb, lab, L), k)
				}
			}
			hm := hmac.New(sha256.New, ia)
			hm.Write(ib)
			check(fmt.Sprintf("hmac(key=%s,msg=%s)", na, nb), hm.Sum(nil))
		}
	}
	// xor-based
	h1 := sha256.Sum256(pk)
	h2 := sha256.Sum256(eph)
	x := make([]byte, 4)
	for i := range x {
		x[i] = h1[i] ^ h2[i]
	}
	check("sha256(pk)^sha256(eph)", x)
	h1 = sha256.Sum256(pkc)
	h2 = sha256.Sum256(ephc)
	for i := range x {
		x[i] = h1[i] ^ h2[i]
	}
	check("sha256(pkc)^sha256(ephc)", x)
	fmt.Println("done", count)
}
