package armor

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
)

const (
	Header = "-----BEGIN AGE ENCRYPTED FILE-----"
	Footer = "-----END AGE ENCRYPTED FILE-----"
)

const columnsPerLine = 64
const bytesPerLine = columnsPerLine / 4 * 3

type armoredWriter struct {
	started, closed bool
	encoder         io.WriteCloser
	dst             io.Writer
	buf             bytes.Buffer
	written         int
}

// NewWriter returns an io.WriteCloser that armors everything written to it
// and writes it to dst. Close must be called to flush the final line and the
// footer.
func NewWriter(dst io.Writer) io.WriteCloser {
	w := &armoredWriter{dst: dst}
	w.encoder = base64.NewEncoder(base64.StdEncoding, writerFunc(w.writeWrapped))
	return w
}

type writerFunc func(p []byte) (int, error)

func (f writerFunc) Write(p []byte) (int, error) { return f(p) }

func (a *armoredWriter) Write(p []byte) (int, error) {
	if !a.started {
		if _, err := io.WriteString(a.dst, Header+"\n"); err != nil {
			return 0, err
		}
		a.started = true
	}
	return a.encoder.Write(p)
}

func (a *armoredWriter) writeWrapped(p []byte) (int, error) {
	n := len(p)
	for len(p) > 0 {
		remainingInLine := columnsPerLine - a.written
		toWrite := len(p)
		if toWrite > remainingInLine {
			toWrite = remainingInLine
		}
		if _, err := a.dst.Write(p[:toWrite]); err != nil {
			return 0, err
		}
		a.written += toWrite
		p = p[toWrite:]
		if a.written == columnsPerLine {
			if _, err := io.WriteString(a.dst, "\n"); err != nil {
				return 0, err
			}
			a.written = 0
		}
	}
	return n, nil
}

func (a *armoredWriter) Close() error {
	if a.closed {
		return errors.New("armor: already closed")
	}
	a.closed = true
	if !a.started {
		if _, err := io.WriteString(a.dst, Header+"\n"); err != nil {
			return err
		}
		a.started = true
	}
	if err := a.encoder.Close(); err != nil {
		return err
	}
	if a.written > 0 {
		if _, err := io.WriteString(a.dst, "\n"); err != nil {
			return err
		}
	}
	_, err := io.WriteString(a.dst, Footer+"\n")
	return err
}

type armoredReader struct {
	r       *bufio.Reader
	started bool
	unread  []byte // backed by buf
	buf     [bytesPerLine]byte
	err     error
}

// NewReader returns an io.Reader that decodes the armored input read from r.
func NewReader(r io.Reader) io.Reader {
	return &armoredReader{r: bufio.NewReader(r)}
}

// Error is the type of errors returned when the input is not valid armor.
type Error struct {
	err error
}

func (e *Error) Error() string {
	return "invalid armor: " + e.err.Error()
}

func (e *Error) Unwrap() error {
	return e.err
}

func errorf(format string, a ...interface{}) error {
	return &Error{fmt.Errorf(format, a...)}
}

func (r *armoredReader) Read(p []byte) (int, error) {
	if len(r.unread) > 0 {
		n := copy(p, r.unread)
		r.unread = r.unread[n:]
		return n, nil
	}
	if r.err != nil {
		return 0, r.err
	}

	getLine := func() ([]byte, error) {
		line, err := r.r.ReadBytes('\n')
		if err == io.EOF && len(line) == 0 {
			return nil, io.ErrUnexpectedEOF
		} else if err != nil && err != io.EOF {
			return nil, err
		}
		line = bytes.TrimSuffix(line, []byte("\n"))
		line = bytes.TrimSuffix(line, []byte("\r"))
		return line, nil
	}

