	drainTrailing := func() error {
		buf, err := io.ReadAll(io.LimitReader(r.r, maxWhitespace))
		if err != nil {
			return err
		}
		if len(bytes.TrimSpace(buf)) != 0 {
			return errorf("trailing data after armored file")
		}
		if len(buf) == maxWhitespace {
			return errorf("too much trailing whitespace")
		}
		return io.EOF
	}

	var removedWhitespace int
	for !r.started {
		peek, err := r.r.Peek(1)
		if err != nil {
			r.err = err
			return 0, err
		}
		if isWhitespace(peek[0]) {
			r.r.Discard(1)
			removedWhitespace++
			if removedWhitespace > maxWhitespace {
				r.err = errorf("too much leading whitespace")
				return 0, r.err
			}
			continue
		}
		line, err := getLine()
		if err != nil {
			r.err = err
			return 0, err
		}
		if string(line) != Header {
			r.err = errorf("invalid first line: %q", line)
			return 0, r.err
		}
		r.started = true
	}

	line, err := getLine()
	if err != nil {
		r.err = errorf("%w", err)
		return 0, r.err
	}
	if string(line) == Footer {
		r.err = drainTrailing()
		return 0, r.err
	}
	if len(line) > columnsPerLine {
		r.err = errorf("column limit exceeded")
		return 0, r.err
	}
	r.unread = r.buf[:]
	n, err := base64.StdEncoding.Strict().Decode(r.unread, line)
	if err != nil {
		r.err = errorf("%w", err)
		return 0, r.err
	}
	r.unread = r.unread[:n]

	if n < bytesPerLine {
		line, err := getLine()
		if err != nil {
			r.err = errorf("%w", err)
			return 0, r.err
		}
		if string(line) != Footer {
			r.err = errorf("invalid closing line: %q", line)
			return 0, r.err
		}
		r.err = drainTrailing()
	}

	nn := copy(p, r.unread)
	r.unread = r.unread[nn:]
	return nn, nil
}

func isWhitespace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}
