package agecore

import (
	"crypto/ecdh"
	"crypto/ed25519"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/sha512"
	"errors"
	"fmt"
	"math/big"

	"agecli/internal/format"

	"golang.org/x/crypto/ssh"
)

const (
	sshRSALabel     = "age-encryption.org/v1/ssh-rsa"
	sshEd25519Label = "age-encryption.org/v1/ssh-ed25519"
)

// ParseSSHRecipient parses an SSH public key in authorized_keys format.
func ParseSSHRecipient(s string) (Recipient, error) {
	pubKey, _, _, _, err := ssh.ParseAuthorizedKey([]byte(s))
	if err != nil {
		return nil, fmt.Errorf("malformed SSH recipient: %q: %v", s, err)
	}

	var r Recipient
	switch t := pubKey.Type(); t {
	case "ssh-rsa":
		r, err = NewSSHRSARecipient(pubKey)
	case "ssh-ed25519":
		r, err = NewSSHEd25519Recipient(pubKey)
	default:
		return nil, fmt.Errorf("unknown SSH recipient type: %q", t)
	}
	if err != nil {
		return nil, fmt.Errorf("malformed SSH recipient: %q: %v", s, err)
	}
	return r, nil
}

func sshFingerprint(pk ssh.PublicKey) string {
	h := sha256.Sum256(pk.Marshal())
	return format.EncodeToString(h[:4])
}

// SSHRSARecipient is the ssh-rsa recipient type.
type SSHRSARecipient struct {
	sshKey ssh.PublicKey
	pubKey *rsa.PublicKey
}

// NewSSHRSARecipient returns a new SSHRSARecipient from a ssh-rsa public key.
func NewSSHRSARecipient(pk ssh.PublicKey) (*SSHRSARecipient, error) {
	if pk.Type() != "ssh-rsa" {
		return nil, errors.New("SSH public key is not an RSA key")
	}
	r := &SSHRSARecipient{sshKey: pk}

	if pk, ok := pk.(ssh.CryptoPublicKey); ok {
		if pk, ok := pk.CryptoPublicKey().(*rsa.PublicKey); ok {
			r.pubKey = pk
		} else {
			return nil, errors.New("unexpected public key type")
		}
	} else {
		return nil, errors.New("pk does not implement ssh.CryptoPublicKey")
	}
	if r.pubKey.Size() < 2048/8 {
		return nil, errors.New("RSA key size is too small")
	}
	return r, nil
}

// Wrap implements Recipient.
func (r *SSHRSARecipient) Wrap(fileKey []byte) ([]*Stanza, error) {
	l := &Stanza{
		Type: "ssh-rsa",
		Args: []string{sshFingerprint(r.sshKey)},
	}

	wrappedKey, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, r.pubKey, fileKey, []byte(sshRSALabel))
	if err != nil {
		return nil, err
	}
	l.Body = wrappedKey

	return []*Stanza{l}, nil
}

// SSHRSAIdentity is the ssh-rsa identity type.
type SSHRSAIdentity struct {
	k      *rsa.PrivateKey
	sshKey ssh.PublicKey
}

