func identityFromSSHKey(k interface{}) (Identity, error) {
	switch k := k.(type) {
	case *ed25519.PrivateKey:
		return NewSSHEd25519Identity(*k)
	case ed25519.PrivateKey:
		return NewSSHEd25519Identity(k)
	case *rsa.PrivateKey:
		return NewSSHRSAIdentity(k)
	}
	return nil, fmt.Errorf("unsupported SSH identity type: %T", k)
}

// SSHRecipientFromIdentity returns the recipient of a parsed SSH identity.
func SSHRecipientFromIdentity(id Identity) (Recipient, error) {
	switch id := id.(type) {
	case *SSHEd25519Identity:
		return id.Recipient(), nil
	case *SSHRSAIdentity:
		return id.Recipient(), nil
	case *EncryptedSSHIdentity:
		return id.Recipient()
	}
	return nil, fmt.Errorf("unsupported SSH identity type: %T", id)
}

// EncryptedSSHIdentity is an SSH identity whose private key is encrypted and
// is decrypted on demand with the passphrase callback.
type EncryptedSSHIdentity struct {
	pubKey     ssh.PublicKey
	pemBytes   []byte
	passphrase func() ([]byte, error)

	decrypted Identity
}

// NewEncryptedSSHIdentity returns a new EncryptedSSHIdentity.
func NewEncryptedSSHIdentity(pubKey ssh.PublicKey, pemBytes []byte, passphrase func() ([]byte, error)) (*EncryptedSSHIdentity, error) {
	switch t := pubKey.Type(); t {
	case "ssh-ed25519", "ssh-rsa":
	default:
		return nil, fmt.Errorf("unsupported SSH key type: %v", t)
	}
	return &EncryptedSSHIdentity{
		pubKey:     pubKey,
		pemBytes:   pemBytes,
		passphrase: passphrase,
	}, nil
}

// Recipient returns the recipient corresponding to the public key.
func (i *EncryptedSSHIdentity) Recipient() (Recipient, error) {
	switch t := i.pubKey.Type(); t {
	case "ssh-ed25519":
		return NewSSHEd25519Recipient(i.pubKey)
	case "ssh-rsa":
		return NewSSHRSARecipient(i.pubKey)
	default:
		return nil, fmt.Errorf("unsupported SSH key type: %v", t)
	}
}

// Unwrap implements Identity. It only requests the passphrase if a stanza
// matches the public key.
func (i *EncryptedSSHIdentity) Unwrap(stanzas []*Stanza) ([]byte, error) {
	var match bool
	for _, s := range stanzas {
		if s.Type != i.pubKey.Type() {
			continue
		}
		if len(s.Args) < 1 {
			return nil, fmt.Errorf("invalid %v recipient block", i.pubKey.Type())
		}
		if s.Args[0] != sshFingerprint(i.pubKey) {
			continue
		}
		match = true
		break
	}
	if !match {
		return nil, ErrIncorrectIdentity
	}

	if i.decrypted != nil {
		return i.decrypted.Unwrap(stanzas)
	}

	passphrase, err := i.passphrase()
	if err != nil {
		return nil, fmt.Errorf("failed to obtain passphrase: %v", err)
	}
	k, err := ssh.ParseRawPrivateKeyWithPassphrase(i.pemBytes, passphrase)
	if err != nil {
		return nil, fmt.Errorf("failed to decrypt SSH key file: %v", err)
	}

	decrypted, err := identityFromSSHKey(k)
	if err != nil {
		return nil, fmt.Errorf("invalid SSH key: %v", err)
	}
	i.decrypted = decrypted
	return i.decrypted.Unwrap(stanzas)
}
