func (r *Recipient) WrapWithLabels(fileKey []byte) ([]*agecore.Stanza, []string, error) {
	conn, err := openClientConnection(r.name, "recipient-v1")
	if err != nil {
		return nil, nil, &Error{r.name, fmt.Errorf("couldn't start plugin: %v", err)}
	}
	defer conn.Close()

	addType := "add-recipient"
	if r.identity {
		addType = "add-identity"
	}
	if err := writeStanza(conn.stdin, addType, r.encoding); err != nil {
		return nil, nil, &Error{r.name, err}
	}
	if err := writeGrease(conn.stdin); err != nil {
		return nil, nil, &Error{r.name, err}
	}
	if err := writeStanzaWithBody(conn.stdin, "wrap-file-key", fileKey); err != nil {
		return nil, nil, &Error{r.name, err}
	}
	if err := writeStanza(conn.stdin, "extension-labels"); err != nil {
		return nil, nil, &Error{r.name, err}
	}
	if err := writeStanza(conn.stdin, "done"); err != nil {
		return nil, nil, &Error{r.name, err}
	}

	var stanzas []*agecore.Stanza
	var labels []string
	var hasLabels bool
	err = conn.handleResponses(r.ui, func(s *format.Stanza) (handled bool, err error) {
		switch s.Type {
		case "recipient-stanza":
			if len(s.Args) < 2 {
				return false, errors.New("malformed recipient stanza")
			}
			n, err := strconv.Atoi(s.Args[0])
			if err != nil || n != 0 {
				return false, errors.New("malformed recipient stanza: unexpected index")
			}
			stanzas = append(stanzas, &agecore.Stanza{
				Type: s.Args[1],
				Args: s.Args[2:],
				Body: s.Body,
			})
			return true, nil
		case "labels":
			if hasLabels {
				return false, errors.New("repeated labels stanza")
			}
			hasLabels = true
			labels = s.Args
			return true, nil
		case "error":
			if len(s.Args) < 1 {
				return false, errors.New("malformed error stanza")
			}
			switch s.Args[0] {
			case "recipient", "identity":
				if len(s.Args) != 2 {
					return false, errors.New("malformed error stanza")
				}
			case "internal":
				if len(s.Args) != 1 {
					return false, errors.New("malformed error stanza")
				}
			default:
				return false, errors.New("malformed error stanza")
			}
			return false, errors.New(string(s.Body))
		}
		return false, nil
	})
	if err != nil {
		return nil, nil, &Error{r.name, err}
	}
	if len(stanzas) == 0 {
		return nil, nil, &Error{r.name, errors.New("received zero recipient stanzas")}
	}
	return stanzas, labels, nil
}

// Identity is a plugin identity.
type Identity struct {
	name     string
	encoding string
	ui       *ClientUI
}

// NewIdentity parses a plugin identity of the form AGE-PLUGIN-NAME-1...
func NewIdentity(s string, ui *ClientUI) (*Identity, error) {
	name, _, err := ParseIdentity(s)
	if err != nil {
		return nil, err
	}
	return &Identity{name: name, encoding: s, ui: ui}, nil
}

// NewIdentityWithoutData returns an identity for a plugin that encodes no data.
func NewIdentityWithoutData(name string, ui *ClientUI) (*Identity, error) {
	if !validName(name) {
		return nil, fmt.Errorf("invalid plugin name: %q", name)
	}
	s, err := EncodeIdentity(name, nil)
	if err != nil {
		return nil, err
	}
	return &Identity{name: name, encoding: s, ui: ui}, nil
}

// ParseIdentity returns the plugin name and data of a plugin identity.
func ParseIdentity(s string) (name string, data []byte, err error) {
	hrp, data, err := bech32.Decode(s)
	if err != nil {
		return "", nil, fmt.Errorf("invalid identity encoding: %v", err)
	}
	if !strings.HasPrefix(hrp, "AGE-PLUGIN-") || !strings.HasSuffix(hrp, "-") {
		return "", nil, fmt.Errorf("not a plugin identity %q", s)
	}
	name = strings.ToLower(strings.TrimSuffix(strings.TrimPrefix(hrp, "AGE-PLUGIN-"), "-"))
	if !validName(name) {
		return "", nil, fmt.Errorf("invalid plugin name: %q", name)
	}
	return name, data, nil
}

// EncodeIdentity encodes a plugin identity.
func EncodeIdentity(name string, data []byte) (string, error) {
	s, err := bech32.Encode("AGE-PLUGIN-"+strings.ToUpper(name)+"-", data)
	if err != nil {
		return "", err
	}
	return strings.ToUpper(s), nil
}

// Name returns the plugin name.
func (i *Identity) Name() string { return i.name }

// String returns the identity encoding.
func (i *Identity) String() string { return i.encoding }

// Recipient returns a Recipient that encrypts to this identity using the
// recipient-v1 protocol with an add-identity stanza.
func (i *Identity) Recipient() *Recipient {
	return &Recipient{name: i.name, encoding: i.encoding, ui: i.ui, identity: true}
}

// Unwrap implements agecore.Identity.
func (i *Identity) Unwrap(stanzas []*agecore.Stanza) ([]byte, error) {
	conn, err := openClientConnection(i.name, "identity-v1")
	if err != nil {
		return nil, &Error{i.name, fmt.Errorf("couldn't start plugin: %v", err)}
	}
	defer conn.Close()

	if err := writeStanza(conn.stdin, "add-identity", i.encoding); err != nil {
		return nil, &Error{i.name, err}
	}
	if err := writeGrease(conn.stdin); err != nil {
		return nil, &Error{i.name, err}
	}
	for _, rs := range stanzas {
		s := &format.Stanza{
			Type: "recipient-stanza",
			Args: append([]string{"0", rs.Type}, rs.Args...),
			Body: rs.Body,
		}
		if err := s.Marshal(conn.stdin); err != nil {
			return nil, &Error{i.name, err}
		}
	}
	if err := writeStanza(conn.stdin, "done"); err != nil {
		return nil, &Error{i.name, err}
	}

	var fileKey []byte
	err = conn.handleResponses(i.ui, func(s *format.Stanza) (handled bool, err error) {
		switch s.Type {
		case "file-key":
			if len(s.Args) != 1 {
				return false, errors.New("malformed file-key stanza")
			}
			n, err := strconv.Atoi(s.Args[0])
			if err != nil || n != 0 {
				return false, errors.New("malformed file-key stanza: unexpected index")
			}
			if fileKey != nil {
				return false, errors.New("repeated file-key stanza")
			}
			fileKey = s.Body
			return true, nil
		case "error":
			if len(s.Args) < 1 {
				return false, errors.New("malformed error stanza")
			}
			switch s.Args[0] {
			case "identity":
				if len(s.Args) != 2 {
					return false, errors.New("malformed error stanza")
				}
			case "stanza":
				if len(s.Args) != 3 {
					return false, errors.New("malformed error stanza")
				}
			case "internal":
				if len(s.Args) != 1 {
					return false, errors.New("malformed error stanza")
				}
			default:
				return false, errors.New("malformed error stanza")
			}
			return false, errors.New(string(s.Body))
		}
		return false, nil
	})
	if err != nil {
		return nil, &Error{i.name, err}
	}
	if fileKey == nil {
		return nil, agecore.ErrIncorrectIdentity
	}
	return fileKey, nil
}

type clientConnection struct {
	name   string
	cmd    *exec.Cmd
	stdin  io.WriteCloser
	stdout *bufio.Reader
	closeW io.Closer
}

func openClientConnection(name, protocol string) (*clientConnection, error) {
	path, err := exec.LookPath("age-plugin-" + name)
	if err != nil {
		return nil, &NotFoundError{Name: name, err: err}
	}
	cmd := exec.Command(path, "--age-plugin="+protocol)
	cmd.Stderr = os.Stderr
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return nil, err
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return nil, err
	}
	if err := cmd.Start(); err != nil {
		return nil, err
	}
	return &clientConnection{
		name:   name,
		cmd:    cmd,
		stdin:  stdin,
		stdout: bufio.NewReader(stdout),
		closeW: stdout,
	}, nil
}

func (c *clientConnection) Close() {
	c.stdin.Close()
	c.closeW.Close()
	c.cmd.Wait()
}

// handleResponses reads stanzas from the plugin until a done stanza,
// dispatching interaction stanzas to the UI and the rest to handle.
func (c *clientConnection) handleResponses(ui *ClientUI, handle func(*format.Stanza) (bool, error)) error {
	sr := format.NewStanzaReader(c.stdout)
	var timer *time.Timer
	if ui != nil && ui.WaitTimer != nil {
		timer = time.AfterFunc(5*time.Second, func() { ui.WaitTimer(c.name) })
	}
	first := true
	for {
		s, err := sr.ReadStanza()
		if first && timer != nil {
			timer.Stop()
			first = false
		}
		if err != nil {
			return err
		}
		switch s.Type {
		case "done":
			return nil
		case "msg":
			if ui == nil || ui.DisplayMessage == nil {
				if err := writeStanza(c.stdin, "unsupported"); err != nil {
					return err
				}
				continue
			}
			if err := ui.DisplayMessage(c.name, string(s.Body)); err != nil {
				if err := writeStanza(c.stdin, "fail"); err != nil {
					return err
				}
				continue
			}
			if err := writeStanza(c.stdin, "ok"); err != nil {
				return err
			}
		case "request-secret", "request-public":
			if ui == nil || ui.RequestValue == nil {
				if err := writeStanza(c.stdin, "unsupported"); err != nil {
					return err
				}
				continue
			}
			value, err := ui.RequestValue(c.name, string(s.Body), s.Type == "request-secret")
			if err != nil {
				if err := writeStanza(c.stdin, "fail"); err != nil {
					return err
				}
				continue
			}
			if err := writeStanzaWithBody(c.stdin, "ok", []byte(value)); err != nil {
				return err
			}
		case "confirm":
			if ui == nil || ui.Confirm == nil {
				if err := writeStanza(c.stdin, "unsupported"); err != nil {
					return err
				}
				continue
			}
			if len(s.Args) < 1 || len(s.Args) > 2 {
				return errors.New("malformed confirm stanza")
			}
			yes, err := format.DecodeString(s.Args[0])
			if err != nil {
				return fmt.Errorf("malformed confirm stanza: %v", err)
			}
			var no []byte
			if len(s.Args) == 2 {
				no, err = format.DecodeString(s.Args[1])
				if err != nil {
					return fmt.Errorf("malformed confirm stanza: %v", err)
				}
			}
			choice, err := ui.Confirm(c.name, string(s.Body), string(yes), string(no))
			if err != nil {
				if err := writeStanza(c.stdin, "fail"); err != nil {
					return err
				}
				continue
			}
			if choice {
				err = writeStanza(c.stdin, "ok", "yes")
			} else {
				err = writeStanza(c.stdin, "ok", "no")
			}
			if err != nil {
				return err
			}
		default:
			handled, err := handle(s)
			if err != nil {
				return err
			}
			if !handled {
				if err := writeStanza(c.stdin, "unsupported"); err != nil {
					return err
				}
				continue
			}
			if err := writeStanza(c.stdin, "ok"); err != nil {
				return err
			}
		}
	}
}

func writeStanza(w io.Writer, t string, args ...string) error {
	s := &format.Stanza{Type: t, Args: args}
	return s.Marshal(w)
}

func writeStanzaWithBody(w io.Writer, t string, body []byte) error {
	s := &format.Stanza{Type: t, Body: body}
	return s.Marshal(w)
}

// writeGrease writes a random grease stanza with 50% probability, to ensure
// plugins correctly ignore unknown stanzas.
func writeGrease(w io.Writer) error {
	if randInt(2) == 0 {
		return nil
	}
	var b [8]byte
	rand.Read(b[:])
	s := &format.Stanza{Type: fmt.Sprintf("grease-%x", binary.BigEndian.Uint64(b[:])>>1)}
	for i := randInt(3); i > 0; i-- {
		s.Args = append(s.Args, strconv.Itoa(randInt(100)))
	}
	if randInt(2) == 0 {
		s.Body = make([]byte, randInt(100))
		rand.Read(s.Body)
	}
	return s.Marshal(w)
}

func randInt(n int) int {
	var b [8]byte
	rand.Read(b[:])
	return int(binary.BigEndian.Uint64(b[:]) % uint64(n))
}

