package agecore

import (
	"crypto/ecdh"
	"crypto/mlkem"
	"crypto/rand"
	"crypto/sha3"
	"errors"
)

// This file implements the ML-KEM-768 + X25519 hybrid KEM (X-Wing style)
// used by the mlkem768x25519 recipient type, as well as the ML-KEM-768 +
// P-256 hybrid used by the mlkem768p256tag recipient type.

const (
	mlkem768CiphertextSize       = 1088
	mlkem768EncapsulationKeySize = 1184
	hybridSeedSize               = 32
)

var errInvalidPublicKeySize = errors.New("invalid public key size")
var errInvalidEncapsulatedKeySize = errors.New("invalid encapsulated key size")

// xwingLabel is the X-Wing combiner label.
var xwingLabel = []byte("\\.//^\\")

// hybridX25519Public is the public half of an ML-KEM-768 + X25519 hybrid key.
type hybridX25519Public struct {
	ek  *mlkem.EncapsulationKey768
	pkX *ecdh.PublicKey
}

func newHybridX25519Public(b []byte) (*hybridX25519Public, error) {
	if len(b) != mlkem768EncapsulationKeySize+32 {
		return nil, errInvalidPublicKeySize
	}
	ek, err := mlkem.NewEncapsulationKey768(b[:mlkem768EncapsulationKeySize])
	if err != nil {
		return nil, err
	}
	pkX, err := ecdh.X25519().NewPublicKey(b[mlkem768EncapsulationKeySize:])
	if err != nil {
		return nil, err
	}
	return &hybridX25519Public{ek: ek, pkX: pkX}, nil
}

func (p *hybridX25519Public) bytes() []byte {
	out := make([]byte, 0, mlkem768EncapsulationKeySize+32)
	out = append(out, p.ek.Bytes()...)
	out = append(out, p.pkX.Bytes()...)
	return out
}

// encapsulate returns the shared secret and the encapsulated key.
func (p *hybridX25519Public) encapsulate() (ss, enc []byte, err error) {
	ssM, ctM := p.ek.Encapsulate()
	eph, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	ctX := eph.PublicKey().Bytes()
	ssX, err := eph.ECDH(p.pkX)
	if err != nil {
		return nil, nil, err
	}
	ss = xwingCombiner(ssM, ssX, ctX, p.pkX.Bytes())
	enc = append(append([]byte{}, ctM...), ctX...)
	return ss, enc, nil
}

func xwingCombiner(ssM, ssX, ctX, pkX []byte) []byte {
	h := sha3.New256()
	h.Write(ssM)
	h.Write(ssX)
	h.Write(ctX)
	h.Write(pkX)
	h.Write(xwingLabel)
	return h.Sum(nil)
}

// hybridX25519Private is the private half of an ML-KEM-768 + X25519 hybrid key.
type hybridX25519Private struct {
	seed []byte
	dk   *mlkem.DecapsulationKey768
	skX  *ecdh.PrivateKey
	pub  *hybridX25519Public
}

func newHybridX25519Private(seed []byte) (*hybridX25519Private, error) {
	if len(seed) != hybridSeedSize {
		return nil, errors.New("invalid seed size")
	}
	h := sha3.NewSHAKE256()
	h.Write(seed)
	expanded := make([]byte, 96)
	h.Read(expanded)
	dk, err := mlkem.NewDecapsulationKey768(expanded[:64])
	if err != nil {
		return nil, err
	}
	skX, err := ecdh.X25519().NewPrivateKey(expanded[64:96])
	if err != nil {
		return nil, err
	}
	return &hybridX25519Private{
		seed: append([]byte{}, seed...),
		dk:   dk,
		skX:  skX,
		pub:  &hybridX25519Public{ek: dk.EncapsulationKey(), pkX: skX.PublicKey()},
	}, nil
}

func (p *hybridX25519Private) decapsulate(enc []byte) ([]byte, error) {
	if len(enc) != mlkem768CiphertextSize+32 {
		return nil, errInvalidEncapsulatedKeySize
	}
	ctM, ctX := enc[:mlkem768CiphertextSize], enc[mlkem768CiphertextSize:]
	ssM, err := p.dk.Decapsulate(ctM)
	if err != nil {
		return nil, err
	}
	pk, err := ecdh.X25519().NewPublicKey(ctX)
	if err != nil {
		return nil, err
	}
	ssX, err := p.skX.ECDH(pk)
	if err != nil {
		return nil, err
	}
	return xwingCombiner(ssM, ssX, ctX, p.pub.pkX.Bytes()), nil
}
EOF
