package agecore

import (
	"crypto/rand"
	"errors"
	"fmt"
	"strings"

	"agecli/internal/bech32"
	"agecli/internal/format"
)

const mlkem768x25519Label = "age-encryption.org/v1/mlkem768x25519"

// MLKEM768X25519Recipient is the native post-quantum age public key.
type MLKEM768X25519Recipient struct {
	pub      *hybridX25519Public
	encoding string
}

// ParseMLKEM768X25519Recipient parses an "age1pq1..." recipient string.
func ParseMLKEM768X25519Recipient(s string) (*MLKEM768X25519Recipient, error) {
	t, k, err := bech32.Decode(s)
	if err != nil {
		return nil, fmt.Errorf("malformed recipient %q: %v", s, err)
	}
	if t != "age1pq" {
		return nil, fmt.Errorf("malformed recipient %q: invalid type %q", s, t)
	}
	pub, err := newHybridX25519Public(k)
	if err != nil {
		return nil, fmt.Errorf("malformed recipient %q: invalid MLKEM768-X25519 public key", s)
	}
	return &MLKEM768X25519Recipient{pub: pub, encoding: s}, nil
}

// String returns the Bech32 encoding of the recipient.
func (r *MLKEM768X25519Recipient) String() string {
	if r.encoding != "" {
		return r.encoding
	}
	s, _ := bech32.Encode("age1pq", r.pub.bytes())
	return s
}

// WrapWithLabels implements RecipientWithLabels.
func (r *MLKEM768X25519Recipient) WrapWithLabels(fileKey []byte) ([]*Stanza, []string, error) {
	s, err := r.Wrap(fileKey)
	return s, []string{PostQuantumLabel}, err
}

// Wrap implements Recipient.
func (r *MLKEM768X25519Recipient) Wrap(fileKey []byte) ([]*Stanza, error) {
	ss, enc, err := r.pub.encapsulate()
	if err != nil {
		return nil, err
	}
	l := &Stanza{
		Type: "mlkem768x25519",
		Args: []string{format.EncodeToString(enc)},
	}
	wrappingKey := mlkem768x25519WrapKey(ss, enc, r.pub.bytes())
	wrappedKey, err := aeadEncrypt(wrappingKey, fileKey)
	if err != nil {
		return nil, err
	}
	l.Body = wrappedKey
	return []*Stanza{l}, nil
}

func mlkem768x25519WrapKey(ss, enc, pub []byte) []byte {
	return hkdfSHA256(ss, nil, mlkem768x25519Label, 32)
}

// MLKEM768X25519Identity is the native post-quantum age private key.
type MLKEM768X25519Identity struct {
	priv *hybridX25519Private
}

// GenerateMLKEM768X25519Identity generates a fresh identity.
func GenerateMLKEM768X25519Identity() (*MLKEM768X25519Identity, error) {
	seed := make([]byte, hybridSeedSize)
	if _, err := rand.Read(seed); err != nil {
		return nil, err
	}
	priv, err := newHybridX25519Private(seed)
	if err != nil {
		return nil, err
	}
	return &MLKEM768X25519Identity{priv: priv}, nil
}

// ParseMLKEM768X25519Identity parses an "AGE-SECRET-KEY-PQ-1..." identity string.
func ParseMLKEM768X25519Identity(s string) (*MLKEM768X25519Identity, error) {
	t, k, err := bech32.Decode(s)
	if err != nil {
		return nil, fmt.Errorf("malformed secret key: %v", err)
	}
	if t != "AGE-SECRET-KEY-PQ-" {
		return nil, fmt.Errorf("malformed secret key: unknown type %q", t)
	}
	priv, err := newHybridX25519Private(k)
	if err != nil {
		return nil, errors.New("malformed secret key: invalid MLKEM768-X25519 secret key")
	}
	return &MLKEM768X25519Identity{priv: priv}, nil
}

// Recipient returns the public key corresponding to i.
func (i *MLKEM768X25519Identity) Recipient() *MLKEM768X25519Recipient {
	return &MLKEM768X25519Recipient{pub: i.priv.pub}
}

// String returns the Bech32 private key encoding of i.
func (i *MLKEM768X25519Identity) String() string {
	s, _ := bech32.Encode("AGE-SECRET-KEY-PQ-", i.priv.seed)
	return strings.ToUpper(s)
}

// Unwrap implements Identity.
func (i *MLKEM768X25519Identity) Unwrap(stanzas []*Stanza) ([]byte, error) {
	return multiUnwrap(i.unwrap, stanzas)
}

func (i *MLKEM768X25519Identity) unwrap(block *Stanza) ([]byte, error) {
	if block.Type != "mlkem768x25519" {
		return nil, ErrIncorrectIdentity
	}
	if len(block.Args) != 1 {
		return nil, errors.New("invalid mlkem768x25519 recipient block")
	}
	enc, err := format.DecodeString(block.Args[0])
	if err != nil {
		return nil, fmt.Errorf("failed to parse mlkem768x25519 recipient: %v", err)
	}
	ss, err := i.priv.decapsulate(enc)
	if err != nil {
		return nil, fmt.Errorf("invalid mlkem768x25519 recipient: %v", err)
	}
	wrappingKey := mlkem768x25519WrapKey(ss, enc, i.priv.pub.bytes())
	fileKey, err := aeadDecrypt(wrappingKey, fileKeySize, block.Body)
	if err == errIncorrectCiphertextSize {
		return nil, err
	} else if err != nil {
		return nil, ErrIncorrectIdentity
	}
	return fileKey, nil
}
