)

// stdinInUse is set when standard input has been claimed, to avoid using it for
// multiple purposes.
var stdinInUse bool

func parseRecipient(arg string) (agecore.Recipient, error) {
	switch {
	case strings.HasPrefix(arg, "age1pq1"):
		return agecore.ParseMLKEM768X25519Recipient(arg)
	case strings.HasPrefix(arg, "age1tag1"), strings.HasPrefix(arg, "age1tagpq1"):
