		if err != nil {
			return nil, fmt.Errorf("failed to open file: %v", err)
		}
		defer f.Close()
	}

	b := bufio.NewReader(f)
	p, _ := b.Peek(14) // length of "age-encryption" and "-----BEGIN AGE"
	peeked := string(p)

	switch {
	// An age encrypted file, plain or armored.
	case peeked == "age-encryption" || peeked == "-----BEGIN AGE":
		var r io.Reader = b
		if peeked == "-----BEGIN AGE" {
			r = armor.NewReader(r)
		}
		const privateKeySizeLimit = 1 << 24 // 16 MiB
		contents, err := io.ReadAll(io.LimitReader(r, privateKeySizeLimit))
		if err != nil {
			return nil, fmt.Errorf("failed to read %q: %v", name, err)
		}
		if len(contents) == privateKeySizeLimit {
			return nil, fmt.Errorf("failed to read %q: file too long", name)
		}
		return []agecore.Identity{&EncryptedIdentity{
			Contents: contents,
			Passphrase: func() (string, error) {
				pass, err := readSecret(fmt.Sprintf("Enter passphrase for identity file %q:", name))
				if err != nil {
					return "", fmt.Errorf("could not read passphrase: %v", err)
				}
				return string(pass), nil
			},
			NoMatchWarning: func() {
				warningf("encrypted identity file %q didn't match file's recipients", name)
			},
		}}, nil

	// An SSH private key file.
	case strings.HasPrefix(peeked, "-----BEGIN"):
		const privateKeySizeLimit = 1 << 14 // 16 KiB
		contents, err := io.ReadAll(io.LimitReader(b, privateKeySizeLimit))
		if err != nil {
			return nil, fmt.Errorf("failed to read %q: %v", name, err)
		}
		if len(contents) == privateKeySizeLimit {
			return nil, fmt.Errorf("failed to read %q: file too long", name)
		}
		return parseSSHIdentity(name, contents)

	// An identities file.
	default:
		ids, err := parseIdentities(b)
		if err != nil {
			return nil, fmt.Errorf("failed to read %q: %v", name, err)
		}
		return ids, nil
	}
}

// parseIdentities parses a file with one or more identities, one per line.
func parseIdentities(f io.Reader) ([]agecore.Identity, error) {
	const privateKeySizeLimit = 1 << 24 // 16 MiB
	var ids []agecore.Identity
	scanner := bufio.NewScanner(io.LimitReader(f, privateKeySizeLimit))
	var n int
	for scanner.Scan() {
		n++
		line := scanner.Text()
		if strings.HasPrefix(line, "#") || line == "" {
			continue
		}
		i, err := parseIdentity(line)
		if err != nil {
			return nil, fmt.Errorf("error at line %d: %v", n, err)
		}
		ids = append(ids, i)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("failed to read identities file: %v", err)
	}
	if len(ids) == 0 {
		return nil, fmt.Errorf("no identities found")
	}
	return ids, nil
}

func parseIdentity(s string) (agecore.Identity, error) {
	switch {
	case strings.HasPrefix(s, "AGE-PLUGIN-"):
		return plugin.NewIdentity(s, pluginTerminalUI)
	case strings.HasPrefix(s, "AGE-SECRET-KEY-PQ-1"):
		return agecore.ParseMLKEM768X25519Identity(s)
	case strings.HasPrefix(s, "AGE-SECRET-KEY-1"):
		return agecore.ParseX25519Identity(s)
	case strings.HasPrefix(s, "age1"):
		return nil, fmt.Errorf("apparent recipient found in identities file")
	default:
		return nil, fmt.Errorf("unknown identity type")
	}
}

func parseSSHIdentity(name string, pemBytes []byte) ([]agecore.Identity, error) {
	id, err := agecore.ParseSSHIdentity(pemBytes)
	if sshErr, ok := err.(*ssh.PassphraseMissingError); ok {
		pubKey := sshErr.PublicKey
		if pubKey == nil {
			pubKey, err = readPubFile(name)
			if err != nil {
				return nil, err
			}
		}
		passphrasePrompt := func() ([]byte, error) {
			pass, err := readSecret(fmt.Sprintf("Enter passphrase for %q:", name))
			if err != nil {
				return nil, fmt.Errorf("could not read passphrase for %q: %v", name, err)
			}
			return pass, nil
		}
		i, err := agecore.NewEncryptedSSHIdentity(pubKey, pemBytes, passphrasePrompt)
		if err != nil {
			return nil, err
		}
		return []agecore.Identity{i}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("malformed SSH identity in %q: %v", name, err)
	}

	return []agecore.Identity{id}, nil
}

func readPubFile(name string) (ssh.PublicKey, error) {
	if name == "-" {
		return nil, fmt.Errorf(`failed to obtain public key for "-" SSH key: cannot read ".pub" file when reading private key from STDIN`)
	}
	f, err := os.Open(name + ".pub")
	if err != nil {
		return nil, fmt.Errorf(`failed to obtain public key for %q SSH key: %v

Ensure %q exists, or convert the private key %q to a modern format with "ssh-keygen -p -m RFC4716"`, name, err, name+".pub", name)
	}
	defer f.Close()
	contents, err := io.ReadAll(f)
	if err != nil {
		return nil, fmt.Errorf("failed to read %q: %v", name+".pub", err)
	}
	pubKey, _, _, _, err := ssh.ParseAuthorizedKey(contents)
	if err != nil {
		return nil, fmt.Errorf("failed to parse %q: %v", name+".pub", err)
	}
	return pubKey, nil
}

// identitiesToRecipients converts identities to the corresponding recipients,
// for use in symmetric encryption with -e -i.
func identitiesToRecipients(ids []agecore.Identity) ([]agecore.Recipient, error) {
	var recipients []agecore.Recipient
	for _, id := range ids {
		switch id := id.(type) {
		case *agecore.X25519Identity:
			recipients = append(recipients, id.Recipient())
		case *agecore.MLKEM768X25519Identity:
			recipients = append(recipients, id.Recipient())
		case *plugin.Identity:
			recipients = append(recipients, id.Recipient())
		case *EncryptedIdentity:
			r, err := id.Recipients()
			if err != nil {
				return nil, err
			}
			recipients = append(recipients, r...)
		default:
			r, err := agecore.SSHRecipientFromIdentity(id)
			if err != nil {
				return nil, fmt.Errorf("unexpected identity type: %T", id)
			}
			recipients = append(recipients, r)
		}
	}
	return recipients, nil
}

// EncryptedIdentity is an identity file encrypted with a passphrase, which is
// decrypted on first use.
type EncryptedIdentity struct {
	Contents       []byte
	Passphrase     func() (string, error)
	NoMatchWarning func()

	identities []agecore.Identity
}

var _ agecore.Identity = &EncryptedIdentity{}

// Recipients decrypts the identity file and returns the recipients
// corresponding to the identities it contains.
func (i *EncryptedIdentity) Recipients() ([]agecore.Recipient, error) {
	if i.identities == nil {
		if err := i.decrypt(); err != nil {
			return nil, err
		}
	}
	return identitiesToRecipients(i.identities)
}

// Unwrap implements agecore.Identity.
func (i *EncryptedIdentity) Unwrap(stanzas []*agecore.Stanza) (fileKey []byte, err error) {
	if i.identities == nil {
		if err := i.decrypt(); err != nil {
			return nil, err
		}
	}

	for _, id := range i.identities {
		fileKey, err = id.Unwrap(stanzas)
		if errors.Is(err, agecore.ErrIncorrectIdentity) {
			continue
		}
		if err != nil {
			return nil, err
		}
		return fileKey, nil
	}
	i.NoMatchWarning()
	return nil, agecore.ErrIncorrectIdentity
}

func (i *EncryptedIdentity) decrypt() error {
	f, err := agecore.Parse(bytes.NewReader(i.Contents))
	if err != nil {
		return fmt.Errorf("failed to decrypt identity file: %v", err)
	}
	stanzas := f.Stanzas()
	if len(stanzas) != 1 || stanzas[0].Type != "scrypt" {
		return fmt.Errorf("identity file is encrypted with age but not with a passphrase")
	}
	d, err := f.Unwrap(&LazyScryptIdentity{i.Passphrase})
	if err != nil {
		return fmt.Errorf("failed to decrypt identity file: %v", err)
	}
	i.identities, err = parseIdentities(d)
	return err
}

// LazyScryptIdentity is an scrypt identity that requests the passphrase only
// if the file is actually passphrase-encrypted.
type LazyScryptIdentity struct {
	Passphrase func() (string, error)
}

var _ agecore.Identity = &LazyScryptIdentity{}

// Unwrap implements agecore.Identity.
func (i *LazyScryptIdentity) Unwrap(stanzas []*agecore.Stanza) (fileKey []byte, err error) {
	for _, s := range stanzas {
		if s.Type == "scrypt" && len(stanzas) != 1 {
			return nil, errors.New("an scrypt recipient must be the only one")
		}
	}
	if len(stanzas) != 1 || stanzas[0].Type != "scrypt" {
		return nil, agecore.ErrIncorrectIdentity
	}
	pass, err := i.Passphrase()
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: %v", err)
	}
	ii, err := agecore.NewScryptIdentity(pass)
	if err != nil {
		return nil, err
	}
	fileKey, err = ii.Unwrap(stanzas)
	if errors.Is(err, agecore.ErrIncorrectIdentity) {
		// ScryptIdentity returns ErrIncorrectIdentity for an incorrect
		// passphrase, which would lead to a confusing error message.
		return nil, fmt.Errorf("incorrect passphrase")
	}
	return fileKey, err
}
