// Command age is a simple, modern, and secure file encryption tool.
package main

import (
	"bytes"
	"crypto/rand"
	"errors"
	"flag"
	"fmt"
	"io"
	"math/big"
	"os"
	"path/filepath"
	"strings"

	"agecli/internal/agecore"
	"agecli/internal/armor"
	"agecli/internal/plugin"
	"agecli/internal/wordlist"

	"golang.org/x/term"
)

const version = "v0.0.0-20260611192840-f11ca54177da"

const usage = `Usage:
    age [--encrypt] (-r RECIPIENT | -R PATH)... [--armor] [-o OUTPUT] [INPUT]
    age [--encrypt] --passphrase [--armor] [-o OUTPUT] [INPUT]
    age --decrypt [-i PATH]... [-o OUTPUT] [INPUT]

Options:
    -e, --encrypt               Encrypt the input to the output. Default if omitted.
    -d, --decrypt               Decrypt the input to the output.
    -o, --output OUTPUT         Write the result to the file at path OUTPUT.
    -a, --armor                 Encrypt to a PEM encoded format.
    -p, --passphrase            Encrypt with a passphrase.
    -r, --recipient RECIPIENT   Encrypt to the specified RECIPIENT. Can be repeated.
    -R, --recipients-file PATH  Encrypt to recipients listed at PATH. Can be repeated.
    -i, --identity PATH         Use the identity file at PATH. Can be repeated.

INPUT defaults to standard input, and OUTPUT defaults to standard output.
If OUTPUT exists, it will be overwritten.

RECIPIENT can be an age public key generated by age-keygen ("age1...")
or an SSH public key ("ssh-ed25519 AAAA...", "ssh-rsa AAAA...").

Recipient files contain one or more recipients, one per line. Empty lines
and lines starting with "#" are ignored as comments. "-" may be used to
read recipients from standard input.

Identity files contain one or more secret keys ("AGE-SECRET-KEY-1..."),
one per line, or an SSH key. Empty lines and lines starting with "#" are
ignored as comments. Passphrase encrypted age files can be used as
identity files. Multiple key files can be provided, and any unused ones
will be ignored. "-" may be used to read identities from standard input.

When --encrypt is specified explicitly, -i can also be used to encrypt to an
identity file symmetrically, instead or in addition to normal recipients.

Example:
    $ age-keygen -o key.txt
    Public key: age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p
    $ tar cvz ~/data | age -r age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p > data.tar.gz.age
    $ age --decrypt -i key.txt -o data.tar.gz data.tar.gz.age`

// Version can be set at link time to override debug.BuildInfo.Main.Version,
// which is "(devel)" when building from within the module. See
// golang.org/issue/29814 and golang.org/issue/29228.
var Version string

func main() {
	_ = flag.CommandLine.Output()
	flag.Usage = func() { fmt.Fprintf(os.Stderr, "%s\n", usage) }

	var (
		outFlag                          string
		decryptFlag, encryptFlag         bool
		passFlag, versionFlag, armorFlag bool
		recipientFlags                   multiFlag
		recipientsFileFlags              multiFlag
		identityFlags                    multiFlag
		pluginFlags                      multiFlag
	)

	flag.BoolVar(&versionFlag, "version", false, "print the version")
	flag.BoolVar(&decryptFlag, "d", false, "decrypt the input")
	flag.BoolVar(&decryptFlag, "decrypt", false, "decrypt the input")
	flag.BoolVar(&encryptFlag, "e", false, "encrypt the input")
	flag.BoolVar(&encryptFlag, "encrypt", false, "encrypt the input")
	flag.BoolVar(&passFlag, "p", false, "use a passphrase")
	flag.BoolVar(&passFlag, "passphrase", false, "use a passphrase")
	flag.StringVar(&outFlag, "o", "", "output to `FILE` (default stdout)")
	flag.StringVar(&outFlag, "output", "", "output to `FILE` (default stdout)")
	flag.BoolVar(&armorFlag, "a", false, "generate an armored file")
	flag.BoolVar(&armorFlag, "armor", false, "generate an armored file")
	flag.Var(&recipientFlags, "r", "recipient (can be repeated)")
	flag.Var(&recipientFlags, "recipient", "recipient (can be repeated)")
	flag.Var(&recipientsFileFlags, "R", "recipients file (can be repeated)")
	flag.Var(&recipientsFileFlags, "recipients-file", "recipients file (can be repeated)")
	flag.Var(&identityFlags, "i", "identity (can be repeated)")
	flag.Var(&identityFlags, "identity", "identity (can be repeated)")
	flag.Var(&pluginFlags, "j", "data-less plugin (can be repeated)")
	flag.Parse()

	if versionFlag {
		if Version != "" {
			fmt.Println(Version)
		} else {
			fmt.Println(version)
		}
		return
	}

	if flag.NArg() > 1 {
		args := flag.Args()
		quoted := make([]string, len(args))
		for i, a := range args {
			quoted[i] = fmt.Sprintf("%q", a)
		}
		msg := "too many INPUT arguments: " + strings.Join(quoted, " ")
		if strings.HasPrefix(args[1], "-") {
			flags := os.Args[1 : len(os.Args)-len(args)]
			cmd := append([]string{os.Args[0]}, flags...)
			cmd = append(cmd, args[1:]...)
			cmd = append(cmd, args[0])
			errorWithHint(msg,
				"the input file must be specified after all flags",
				"did you mean:",
				"    "+strings.Join(cmd, " "))
		}
		errorWithHint(msg, "only a single input file may be specified at a time")
	}

	switch {
	case decryptFlag && encryptFlag:
		errorf("-e/--encrypt can't be used with -d/--decrypt")
	case decryptFlag && armorFlag:
		errorWithHint("-a/--armor can't be used with -d/--decrypt",
			"note that armored files are detected automatically, try again without -a/--armor")
	case decryptFlag && passFlag:
		errorWithHint("-p/--passphrase can't be used with -d/--decrypt",
			"note that password protected files are detected automatically")
	case decryptFlag && len(recipientFlags) > 0:
		errorWithHint("-r/--recipient can't be used with -d/--decrypt",
			"did you mean to use -i/--identity to specify a private key?")
	case decryptFlag && len(recipientsFileFlags) > 0:
		errorWithHint("-R/--recipients-file can't be used with -d/--decrypt",
			"did you mean to use -i/--identity to specify a private key?")
	case !decryptFlag && !encryptFlag && (len(identityFlags) > 0 || len(pluginFlags) > 0):
		errorWithHint("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt",
			"did you forget to specify -d/--decrypt?")
	case passFlag && len(recipientFlags) > 0:
		errorf("-p/--passphrase can't be combined with -r/--recipient")
	case passFlag && len(recipientsFileFlags) > 0:
		errorf("-p/--passphrase can't be combined with -R/--recipients-file")
	case passFlag && (len(identityFlags) > 0 || len(pluginFlags) > 0):
		errorf("-p/--passphrase can't be combined with -i/--identity and -j")
	case !decryptFlag && !passFlag && len(recipientFlags) == 0 &&
		len(recipientsFileFlags) == 0 && len(identityFlags) == 0 && len(pluginFlags) == 0:
		errorWithHint("missing recipients",
			"did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?")
	}

	var in io.Reader = os.Stdin
	var out io.Writer = os.Stdout
	inputName := flag.Arg(0)
	if inputName != "" && inputName != "-" {
		f, err := os.Open(inputName)
		if err != nil {
			errorf("failed to open input file %q: %v", inputName, err)
		}
		defer f.Close()
		in = f
	} else {
		stdinInUse = true
	}
	if outFlag != "" && outFlag != "-" {
		if inputName != "" && inputName != "-" {
			inAbs, _ := filepath.Abs(inputName)
			outAbs, _ := filepath.Abs(outFlag)
			if inAbs == outAbs {
				errorf("input and output file are the same: %q", outFlag)
			}
		}
		f := newLazyOpener(outFlag)
		defer func() {
			if err := f.Close(); err != nil {
				errorf("failed to close output file %q: %v", outFlag, err)
			}
		}()
		out = f
	} else if term.IsTerminal(int(os.Stdout.Fd())) {
		if outFlag != "-" {
			if decryptFlag {
				// TODO: buffer the output and check it's printable.
			} else if !armorFlag {
				// If the output wouldn't be armored, refuse to send binary to
				// the terminal unless explicitly requested with "-o -".
				errorWithHint("refusing to output binary to the terminal",
					"did you mean to use -a/--armor?",
					`force anyway with "-o -"`)
			}
		}
		if in == os.Stdin && term.IsTerminal(int(os.Stdin.Fd())) {
			// If the input comes from a TTY and output will go to a TTY,
			// buffer it up so it doesn't get in the way of typing the input.
			buf := &bytes.Buffer{}
			defer func() { io.Copy(os.Stdout, buf) }()
			out = buf
		}
	}

	switch {
	case decryptFlag:
		decrypt(identityFlags, pluginFlags, in, out)
	case passFlag:
		pass, err := passphrasePromptForEncryption()
		if err != nil {
			errorf("%v", err)
		}
		encryptPass(pass, in, out, armorFlag)
	default:
		encryptNotPass(recipientFlags, recipientsFileFlags, identityFlags, pluginFlags, in, out, armorFlag)
	}
}

func passphrasePromptForEncryption() (string, error) {
	pass, err := readSecret("Enter passphrase (leave empty to autogenerate a secure one):")
	if err != nil {
		return "", fmt.Errorf("could not read passphrase: %v", err)
	}
	p := string(pass)
	if p == "" {
		var words []string
		for i := 0; i < 10; i++ {
			words = append(words, randomWord())
		}
		p = strings.Join(words, "-")
		err := printfToTerminal("using autogenerated passphrase %q", p)
		if err != nil {
			return "", fmt.Errorf("could not print passphrase: %v", err)
		}
	} else {
		confirm, err := readSecret("Confirm passphrase:")
		if err != nil {
			return "", fmt.Errorf("could not read passphrase: %v", err)
		}
		if string(confirm) != p {
			return "", fmt.Errorf("passphrases didn't match")
		}
	}
	return p, nil
}

func randomWord() string {
	n, err := rand.Int(rand.Reader, big.NewInt(int64(len(wordlist.Words))))
	if err != nil {
		errorf("failed to generate random passphrase: %v", err)
	}
	return wordlist.Words[n.Int64()]
}

func encryptNotPass(recs, files, identities, plugins []string, in io.Reader, out io.Writer, armor bool) {
	var recipients []agecore.Recipient
	seen := make(map[string]bool)
	for _, arg := range recs {
		if seen[arg] {
			warningf("duplicate recipient %q", arg)
		}
		seen[arg] = true
		r, err := parseRecipient(arg)
		if err != nil {
			errorf("%v", err)
		}
		recipients = append(recipients, r)
	}
	for _, name := range files {
		recs, err := parseRecipientsFile(name)
		if err != nil {
			errorf("failed to parse recipient file %q: %v", name, err)
		}
		recipients = append(recipients, recs...)
	}
	ids := collectIdentities(identities, plugins)
	recs2, err := identitiesToRecipients(ids)
	if err != nil {
		errorf("%v", err)
	}
	recipients = append(recipients, recs2...)
	encrypt(recipients, in, out, armor)
}

func encryptPass(pass string, in io.Reader, out io.Writer, armor bool) {
	r, err := agecore.NewScryptRecipient(pass)
	if err != nil {
		errorf("%v", err)
	}
	encrypt([]agecore.Recipient{r}, in, out, armor)
}

func encrypt(recipients []agecore.Recipient, in io.Reader, out io.Writer, withArmor bool) {
	if withArmor {
		a := armor.NewWriter(out)
		defer func() {
			if err := a.Close(); err != nil {
				errorf("%v", err)
			}
		}()
		out = a
	}
	w, err := agecore.Encrypt(out, recipients...)
	if err != nil {
		errorf("%v", err)
	}
	if _, err := io.Copy(w, in); err != nil {
		errorf("%v", err)
	}
	if err := w.Close(); err != nil {
		errorf("%v", err)
	}
}

// collectIdentities parses the -i and -j flags in order.
func collectIdentities(identities, plugins []string) []agecore.Identity {
	var ids []agecore.Identity
	seen := make(map[string]bool)
	for _, name := range identityFlagOrder(identities, plugins) {
		if name.plugin {
			id, err := plugin.NewIdentityWithoutData(name.value, pluginTerminalUI)
			if err != nil {
				errorf("initializing %q: %v", name.value, err)
			}
			ids = append(ids, id)
			continue
		}
		if seen[name.value] {
			warningf("duplicate identity file %q", name.value)
		}
		seen[name.value] = true
		i, err := parseIdentitiesFile(name.value)
		if err != nil {
			errorf("reading %q: %v", name.value, err)
		}
		ids = append(ids, i...)
	}
	return ids
}

type identityFlag struct {
	value  string
	plugin bool
}

// identityFlagOrder returns the -i and -j flags in command line order.
func identityFlagOrder(identities, plugins []string) []identityFlag {
	var out []identityFlag
	for _, o := range flagOrder {
		switch o.name {
		case "i", "identity":
			out = append(out, identityFlag{value: o.value})
		case "j":
			out = append(out, identityFlag{value: o.value, plugin: true})
		}
	}
	if len(out) != len(identities)+len(plugins) {
		// Fallback, should not happen.
		out = nil
		for _, i := range identities {
			out = append(out, identityFlag{value: i})
		}
		for _, p := range plugins {
			out = append(out, identityFlag{value: p, plugin: true})
		}
	}
	return out
}

func decrypt(identities, plugins []string, in io.Reader, out io.Writer) {
	ids := collectIdentities(identities, plugins)

	// Native identities are cheap to try and never interactive, so try them
	// first regardless of the order in which they were specified.
	var native, others []agecore.Identity
	for _, id := range ids {
		switch id.(type) {
		case *agecore.X25519Identity, *agecore.MLKEM768X25519Identity:
			native = append(native, id)
		default:
			others = append(others, id)
		}
	}
	ids = append(native, others...)

	rr := newPeekReader(in)
	if intro, _ := rr.Peek(len(crlfMangledIntro)); string(intro) == crlfMangledIntro ||
		string(intro) == utf16MangledIntro {
		errorWithHint("invalid header intro",
			"it looks like this file was corrupted by PowerShell redirection",
			"consider using -o or -a to encrypt files in PowerShell")
	}
	in = rr
	if rr.startsWithArmor() {
		in = armor.NewReader(rr)
	}

	f, err := agecore.Parse(in)
	if err != nil {
		errorf("%v", err)
	}
	stanzas := f.Stanzas()
	isPassphrase := len(stanzas) == 1 && stanzas[0].Type == "scrypt"

	if len(ids) == 0 {
		for _, s := range stanzas {
			if s.Type == "scrypt" && len(stanzas) != 1 {
				errorf("an scrypt recipient must be the only one")
			}
		}
		if !isPassphrase {
			errorWithHint("the file is not passphrase-encrypted, identities are required",
				"specify identities with -i/--identity or -j to decrypt this file")
		}
		ids = append(ids, &LazyScryptIdentity{passphrasePromptForDecryption})
	} else if isPassphrase {
		errorWithHint("file is passphrase-encrypted but identities were specified with -i/--identity or -j",
			"remove all -i/--identity/-j flags to decrypt passphrase-encrypted files")
	}

	r, err := f.Unwrap(ids...)
	if err != nil {
		errorf("%v", err)
	}
	if _, err := io.Copy(out, r); err != nil {
		errorf("%v", err)
	}
}

func passphrasePromptForDecryption() (string, error) {
	pass, err := readSecret("Enter passphrase:")
	if err != nil {
		return "", fmt.Errorf("could not read passphrase: %v", err)
	}
	return string(pass), nil
}

const crlfMangledIntro = "age-encryption.org/v1" + "\r"
const utf16MangledIntro = "\xff\xfe" + "a\x00g\x00e\x00-\x00e\x00n\x00c\x00r\x00y\x00p\x00t\x00i\x00o\x00n\x00.\x00o\x00r\x00g\x00/\x00v\x001\x00"
EOF
