package main

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"os"

	"agecli/internal/armor"
	"agecli/internal/plugin"
)

type multiFlag []string

func (f *multiFlag) String() string { return fmt.Sprint(*f) }

func (f *multiFlag) Set(value string) error {
	*f = append(*f, value)
	return nil
}

type orderedFlagValue struct {
	name  string
	value string
}

// flagOrder records the order in which repeatable flags were specified.
var flagOrder []orderedFlagValue

// namedFlag is a multiFlag that also records the order of the flags.
type namedFlag struct {
	name   string
	target *multiFlag
}

func (f *namedFlag) String() string {
	if f.target == nil {
		return ""
	}
	return f.target.String()
}

func (f *namedFlag) Set(value string) error {
	flagOrder = append(flagOrder, orderedFlagValue{f.name, value})
	return f.target.Set(value)
}

func printf(format string, v ...interface{}) {
	fmt.Fprintf(os.Stderr, "age: "+format+"\n", v...)
}

func warningf(format string, v ...interface{}) {
	fmt.Fprintf(os.Stderr, "age: warning: "+format+"\n", v...)
}

func errorf(format string, v ...interface{}) {
	err := fmt.Errorf(format, v...)
	var hints []string
	var nf *plugin.NotFoundError
	if errors.As(err, &nf) {
		hints = append(hints,
			fmt.Sprintf("you might want to install the %q plugin", nf.Name),
			"visit https://age-encryption.org/awesome#plugins for a list of available plugins")
	}
	errorWithHint(err.Error(), hints...)
}

func errorWithHint(error string, hints ...string) {
	fmt.Fprintf(os.Stderr, "age: error: %s\n", error)
	for _, hint := range hints {
		fmt.Fprintf(os.Stderr, "age: hint: %s\n", hint)
	}
	fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
	exit(1)
}

var exit = os.Exit

// lazyOpener opens the file on the first Write, so that no file is created if
// an error occurs before any output is produced.
type lazyOpener struct {
	name string
	f    *os.File
	err  error
}

func newLazyOpener(name string) io.WriteCloser {
	return &lazyOpener{name: name}
}

func (l *lazyOpener) Write(p []byte) (n int, err error) {
	if l.f == nil && l.err == nil {
		l.f, l.err = os.Create(l.name)
	}
	if l.err != nil {
		return 0, l.err
	}
	return l.f.Write(p)
}

func (l *lazyOpener) Close() error {
	if l.f != nil {
		return l.f.Close()
	}
	return nil
}

// peekReader is a bufio.Reader that can detect armored input.
type peekReader struct {
	*bufio.Reader
}

func newPeekReader(r io.Reader) *peekReader {
	return &peekReader{bufio.NewReaderSize(r, 4096)}
}

// startsWithArmor reports whether the input, ignoring leading whitespace,
// starts with the armor header.
func (r *peekReader) startsWithArmor() bool {
	for n := 1; n <= 4096; n += 32 {
		buf, err := r.Peek(n)
		i := 0
		for i < len(buf) && isSpace(buf[i]) {
			i++
		}
		rest := buf[i:]
		if len(rest) >= len(armor.Header) {
			return string(rest[:len(armor.Header)]) == armor.Header
		}
		if len(rest) > 0 && armor.Header[:len(rest)] != string(rest) {
			return false
		}
		if err != nil {
			return false
		}
	}
	return false
}

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}
